<script lang="ts">
  import { onMount } from 'svelte';
  type Dataset={id:string;name:string;synthetic:boolean;assets:number};
  type Props={datasets:Dataset[];onInspect:(id:string)=>void;onUpdated:()=>void};
  let {datasets,onInspect,onUpdated}:Props=$props();
  type Score={candidateId:string;baseRunId:string;stressRunId:string;baseEndingGbp:number;stressEndingGbp:number;worstMarginGbp:number};
  type Study={id:string;name:string;status:string;planSha256:string;plan:{synthetic:boolean;purpose:string;developmentStart:string;developmentEnd:string;reservedStart:string;reservedEnd:string;accountInitialisation:string;selectionRule:string;candidates:{id:string;config:{topK:number;maximumWeight:number;hypothesis:string}}[]};priorTrials:unknown[];scores:Score[];selectedCandidateId:string|null;errorCode:string|null;finalRequestedAt:string|null;finalPassed:boolean|null;finalWorstMarginGbp:number|null;finalBaseRunId:string|null;finalStressRunId:string|null;selectionDiagnostics:{months:number;candidates:number;comparisons:number;sensitivities:{expectedBlockMonths:number;simultaneousRadius:number}[]}|null};
  type Row={id:string;name:string;status:string;synthetic:boolean;candidates:number;completedRuns:number;plannedRuns:number;selectedCandidateId:string|null;errorCode:string|null};
  let history=$state<Row[]>([]),selected=$state<Study|null>(null),datasetId=$state(''),name=$state('£20 speculative policy study'),busy=$state(false),error=$state('');
  let createRequestId='',createSignature='',wantedStudy='';const evaluations=new Map<string,string>();
  const dataset=$derived(datasets.find(d=>d.id===datasetId));
  const variants=$derived([1,2,4,8].filter(n=>n<=(dataset?.assets??0)));
  const scores=$derived([...(selected?.scores??[])].sort((a,b)=>b.worstMarginGbp-a.worstMarginGbp||a.candidateId.localeCompare(b.candidateId)));
  const current=$derived(history.find(s=>s.id===selected?.id));
  const active=$derived(history.some(s=>['development','final-evaluation'].includes(s.status)));
  const money=(n:number)=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',maximumFractionDigits:2}).format(n);
  const messages:Record<string,string>={'study-known-reserved-exposure':'A prior requested or started local run reaches into this reserved window. It cannot be treated as unseen.','study-reserved-window-conflict':'Another study already reserves these calendar outcomes. This prevents selecting through overlapping final tests.','study-holdout-spent':'This final window has already been requested. Its original run pair remains recorded; it cannot be replaced.','study-code-changed':'The code changed after declaration. This study cannot silently continue under a different implementation.','study-trial-incomplete':'A declared trial failed, was cancelled or was interrupted. The family cannot nominate a winner by dropping that attempt.','study-code-or-state-changed':'The study code or lifecycle changed. Unstarted work was stopped without replacement.','study-development-window-too-short':'This study needs 60 initial training months, label warmup, at least 24 shared development months and 24 reserved months.'};
  async function api(path:string,body?:unknown){const response=await fetch(path,body===undefined?undefined:{method:'POST',headers:{'Content-Type':'application/json','X-Twenty-Request':'1'},body:JSON.stringify(body)});if(!response.ok){const value=await response.json();throw new Error(messages[value.error]??value.error??'study-unavailable');}return response.json();}
  async function refresh(){history=await api('/api/research/studies');const id=wantedStudy;if(id){const result=await api(`/api/research/studies/${id}`);if(wantedStudy===id)selected=result;}onUpdated();}
  async function inspect(id:string){wantedStudy=id;error='';try{selected=await api(`/api/research/studies/${id}`);}catch(e){error=e instanceof Error?e.message:'study-unavailable';}}
  async function register(){if(!dataset)return;busy=true;error='';const payload={datasetId,name,purpose:dataset.synthetic?'engineering':'research',monthlyGbp:20,costs:{fxBps:15,halfSpreadBps:5,slippageBps:5,buyTaxBps:0,minimumOrderGbp:1}};const signature=JSON.stringify(payload);if(signature!==createSignature||!createRequestId){createSignature=signature;createRequestId=crypto.randomUUID();}try{selected=await api('/api/research/studies',{requestId:createRequestId,...payload});wantedStudy=selected!.id;createRequestId='';await refresh();}catch(e){error=e instanceof Error?e.message:'study-unavailable';}finally{busy=false;}}
  async function evaluate(){if(!selected)return;busy=true;error='';const id=selected.id;if(!evaluations.has(id))evaluations.set(id,crypto.randomUUID());try{const result=await api(`/api/research/studies/${id}/evaluate`,{requestId:evaluations.get(id),planSha256:selected.planSha256});if(wantedStudy===id)selected=result;await refresh();}catch(e){error=e instanceof Error?e.message:'study-unavailable';}finally{busy=false;}}
  async function cancel(){if(!selected)return;busy=true;error='';try{await api(`/api/research/studies/${selected.id}/cancel`,{});await refresh();}catch(e){error=e instanceof Error?e.message:'study-unavailable';}finally{busy=false;}}
  $effect(()=>{if(!datasetId&&datasets.length)datasetId=datasets.find(d=>d.name.includes('growth'))?.id??datasets[0].id;});
  onMount(()=>{let stopped=false;void refresh().catch(e=>error=e.message);const timer=setInterval(()=>{if(!stopped&&active)void refresh().catch(e=>error=e.message);},2000);return()=>{stopped=true;clearInterval(timer);};});
</script>
<section class="panel lab-results" aria-labelledby="study-title"><div class="panel-heading"><div><p class="eyebrow">LET TWENTY SELECT THE POLICY</p><h2 id="study-title">Declare the candidates. Freeze one choice.</h2></div><span class="badge">£20 / MONTH · NO SELLING</span></div>
  <p>Compare all four implemented hypotheses across feasible 1, 2, 4 and 8-stock portfolios. Every candidate receives a base-cost and doubled-variable-cost test, identical dates and contributions. Twenty chooses by the declared rule; a failed candidate cannot disappear from the family.</p>
  <form class="signal-form" onsubmit={(e)=>{e.preventDefault();void register();}}><label>Study dataset<select bind:value={datasetId} disabled={busy} required>{#each datasets as d}<option value={d.id}>{d.name}</option>{/each}</select></label><label>Study name<input bind:value={name} maxlength="80" required disabled={busy}/></label><button disabled={busy||!dataset}>{busy?'Recording study…':`Declare and run ${variants.length*8} development trials`}</button></form>
  <p class="dataset-note">{dataset?.synthetic?'Synthetic engineering rehearsal: outcomes are already inspectable and cannot approve live trading.':'Imported research panel: provenance, eligibility and unseen-data claims still require an independent audit.'} 60 initial training months with expanding history; annual refits; final 24 monthly outcomes reserved. Base research costs: 15 bps FX + 5 bps half-spread + 5 bps slippage per side, zero buy tax, £1 minimum. These flat assumptions are not verified instrument costs. One worker runs the declared jobs; there is no periodic study.</p>
  {#if error}<p class="error" role="alert">{error}</p>{/if}
  {#if history.length}<div class="table-scroll"><table><thead><tr><th>Study</th><th>Status</th><th>Completed / declared runs</th><th>Inspect</th></tr></thead><tbody>{#each history as study}<tr><td>{study.name}<small>{study.synthetic?'Engineering rehearsal':'Imported research'}</small></td><td>{study.status}</td><td>{study.completedRuns} / {study.plannedRuns}</td><td><button class="secondary small-button" disabled={busy} onclick={()=>void inspect(study.id)}>Open study</button></td></tr>{/each}</tbody></table></div>{/if}
  {#if selected}
    <h3>{selected.name} · {selected.status}</h3><p class="dataset-note">{selected.plan.candidates.length} frozen candidates · {selected.priorTrials.length} earlier local trials disclosed · shared development {selected.plan.developmentStart}–{selected.plan.developmentEnd} · one-month selection gap · final window {selected.plan.reservedStart}–{selected.plan.reservedEnd}. {current?`${current.completedRuns} recorded completions.`:''}</p>
    <p>{selected.plan.accountInitialisation} This tests a new contribution account in each window; it does not continue the development portfolio into the final window.</p>
    {#if selected.errorCode}<p class="error" role="alert">{messages[selected.errorCode]??selected.errorCode}</p>{/if}
    {#if selected.selectedCandidateId}<p><strong>Frozen choice: {selected.selectedCandidateId}</strong>. Selection rule: {selected.plan.selectionRule}</p>{/if}
    {#if selected.status==='candidate-frozen'}<p>The application has frozen the policy parameters and refit schedule before reading final outcomes. Requesting the fixed final base/stress pair spends this study's window before either job starts. Failure or interruption cannot create replacement tests.</p><button disabled={busy} onclick={()=>void evaluate()}>{selected.plan.synthetic?'Run the final-window rehearsal':'Consume final window and evaluate'}</button>{/if}
    {#if ['development','candidate-frozen','final-evaluation'].includes(selected.status)}<button class="secondary" disabled={busy} onclick={()=>void cancel()}>Stop this study</button>{/if}
    {#if selected.finalRequestedAt}<p class="dataset-note">Final access requested {new Date(selected.finalRequestedAt).toLocaleString('en-GB')}. This request remains spent, including on failure or cancellation.</p>{/if}
    {#if selected.status==='engineering-complete'}<p><strong>Engineering rehearsal complete.</strong> Synthetic results cannot nominate a real investment strategy or approve live execution.</p>{:else if selected.status==='forward-candidate'}<p><strong>Candidate for prospective validation.</strong> Passing the declared historical wealth screen does not establish a durable edge or approve live execution.</p>{:else if selected.status==='rejected'}<p><strong>Retain cash under this research decision.</strong> The frozen candidate failed the final screen. A revised policy needs new prospective evidence; the application cannot substitute a runner-up after seeing final outcomes.</p>{:else if selected.status==='no-candidate'}<p><strong>No candidate passed the development screen.</strong> The final window remains unspent. Later research must disclose these prior searches and cannot treat this family as the whole programme.</p>{/if}
    {#if selected.finalWorstMarginGbp!==null}<p>Final worst base/stress wealth margin: <strong>{money(selected.finalWorstMarginGbp)}</strong>. This is a mechanical research screen, not a statistical confidence level.</p>{/if}
    {#if selected.finalBaseRunId&&['engineering-complete','forward-candidate','rejected'].includes(selected.status)}<button class="secondary small-button" onclick={()=>onInspect(selected!.finalBaseRunId!)}>Inspect final base report</button><button class="secondary small-button" onclick={()=>onInspect(selected!.finalStressRunId!)}>Inspect final stress report</button>{/if}
    {#if scores.length}<div class="table-scroll"><table><caption>Declared candidates ranked by the worst base/stress ending-wealth margin over benchmark, all-asset equal targets and cash. Momentum remains in every report.</caption><thead><tr><th>Candidate</th><th>Base ending GBP</th><th>Stress ending GBP</th><th>Worst margin</th><th>Reports</th></tr></thead><tbody>{#each scores as score}<tr><td>{score.candidateId}{score.candidateId===selected.selectedCandidateId?' · frozen':''}</td><td>{money(score.baseEndingGbp)}</td><td>{money(score.stressEndingGbp)}</td><td>{money(score.worstMarginGbp)}</td><td><button class="secondary small-button" onclick={()=>onInspect(score.baseRunId)}>Base</button><button class="secondary small-button" onclick={()=>onInspect(score.stressRunId)}>Stress</button></td></tr>{/each}</tbody></table></div>{/if}
    {#if selected.selectionDiagnostics}<details><summary>Selection uncertainty and frozen plan</summary><p>{selected.selectionDiagnostics.candidates} base/stress return streams, {selected.selectionDiagnostics.months} common months and {selected.selectionDiagnostics.comparisons} paired comparisons enter the study's joint resampling diagnostic. Positive wealth margins are nomination criteria only; they are not calibrated evidence of alpha. Prior local searches, manual inspection and data quality remain separate limitations.</p><p>Simultaneous annualised mean-active-return radius: {selected.selectionDiagnostics.sensitivities.map(s=>`${s.expectedBlockMonths}-month blocks: ${(s.simultaneousRadius*100).toFixed(2)} percentage points`).join(' · ')}.</p><p class="dataset-note">Plan SHA-256 {selected.planSha256}</p><a class="text-link" href={`/api/research/studies/${selected.id}/plan`} target="_blank" rel="noreferrer">Exact frozen plan JSON ↗</a> <a class="text-link" href={`/api/research/studies/${selected.id}`} target="_blank" rel="noreferrer">Full study, trial hashes and diagnostics ↗</a></details>{/if}
  {/if}
  <a class="text-link" href="https://github.com/Jellman86/twenty/blob/dev/docs/registered-studies.md" target="_blank" rel="noreferrer">Study protocol, final-data rules and limitations ↗</a>
</section>
